function reducer(state, action){
  switch(action.type){
    case 'NAV': return {...state, activeScreen:action.screen};
    case 'SET_ROLE': return {...state, role:action.role};
    case 'SET_QUEUE_FILTER': return {...state, queueFilter:{...state.queueFilter,...action.patch}};
    case 'SET_QUEUE_SEARCH': return {...state, queueSearch:action.value};
    case 'SET_SCORING_STATUS': return {...state, scoringStatus:action.status};
    case 'OPEN_TICKET': return {...state, activeScreen:'unified_context_panel', activeTicketId:action.ticketId, hydration:{identity:'ready',order:'loading',refund:'loading',customer:'loading',suggestions:'loading'}, intentResult:null, eligibility:null, selectedSuggestionId:null, expandedSuggestionId:null, siblingBanner:null, timeline:{drawn:false}};
    case 'HYDRATE_CARD': return {...state, hydration:{...state.hydration,[action.card]:action.status}};
    case 'SET_INTENT': return {...state, intentResult:action.result};
    case 'SET_ELIGIBILITY': return {...state, eligibility:action.result};
    case 'SET_SIBLING_BANNER': return {...state, siblingBanner:action.banner};
    case 'MERGE_SIBLING': return {...state, siblingBanner:null, audit:[{action_id:'ACT-'+Math.floor(500+Math.random()*400),ticket_id:state.activeTicketId,type:'ticket_merge',amount_or_sku:'—',actor:'Maya Torres',ai_confidence:0.88,policy_citation:'—',shopify_ref:action.mergedId||'TKT-merge',timestamp:new Date().toISOString()},...state.audit], toast:{kind:'success',text:'Threads merged — single source of truth'}};
    case 'EXPAND_SUGGESTION': return {...state, expandedSuggestionId: state.expandedSuggestionId===action.id?null:action.id};
    case 'SELECT_SUGGESTION': return {...state, selectedSuggestionId:action.id};
    case 'SET_PROVIDER': return {...state, aiProvider:action.provider, aiFallbackActive:action.fallback};
    case 'DRAW_TIMELINE': return {...state, timeline:{drawn:true}};
    case 'OPEN_SUBSTITUTION': return {...state, activeScreen:'substitution_drawer', substitution:{...state.substitution, open:true, status:'loading', results:[]}};
    case 'SET_SUBSTITUTES': return {...state, substitution:{...state.substitution, status:'ready', results:action.results}};
    case 'SELECT_SUBSTITUTE': return {...state, substitution:{...state.substitution, selectedSku:action.sku}};
    case 'OPEN_COMPOSER': return {...state, activeScreen:'resolution_composer', composer:{...state.composer, open:true, draftStatus:'loading', resolveState:'idle', commitStep:-1, chips:action.chips||state.composer.chips}};
    case 'SET_DRAFT': return {...state, composer:{...state.composer, draft:action.draft, draftStatus:'ready', toneScore:action.tone!=null?action.tone:state.composer.toneScore}};
    case 'EDIT_DRAFT': return {...state, composer:{...state.composer, draft:action.draft}};
    case 'SET_CHIPS': return {...state, composer:{...state.composer, chips:action.chips}};
    case 'SET_POLICY_CITATION': return {...state, composer:{...state.composer, policyCitation:action.citation}};
    case 'SET_RESOLVE_STATE': return {...state, composer:{...state.composer, resolveState:action.value}};
    case 'COMMIT_STEP': return {...state, composer:{...state.composer, commitStep:action.step}};
    case 'SET_REFUND_TRACKER': return {...state, refundTrackerStatus:action.status};
    case 'COMMIT_RESOLUTION': {
      const t = state.tickets.find(x=>x.id===state.activeTicketId);
      const newAudits = (action.entries||[]).map((e,i)=>({action_id:'ACT-'+Math.floor(600+Math.random()*300)+i,ticket_id:state.activeTicketId,actor:'Maya Torres',timestamp:new Date().toISOString(),...e}));
      return {...state, audit:[...newAudits,...state.audit], tickets:state.tickets.map(x=>x.id===state.activeTicketId?{...x,status:'resolved'}:x), toast:{kind:'success',text:'Resolved — customer notified'}, refundTrackerStatus:'settled'};
    }
    case 'AUTO_ADVANCE': return {...state, activeScreen:'escalation_queue', activeTicketId:null, composer:{...state.composer, open:false, resolveState:'idle', commitStep:-1}};
    case 'OPEN_GOODWILL': return {...state, goodwill:{...state.goodwill, open:true, status:'idle'}};
    case 'SET_GOODWILL_AMOUNT': { const over = action.amount>state.agentCreditLimit; return {...state, goodwill:{...state.goodwill, amount:action.amount, ctaMode:over?'request':'issue'}}; }
    case 'SET_GOODWILL_RECOMMENDED': return {...state, goodwill:{...state.goodwill, recommended:action.amount, amount:action.amount}};
    case 'GOODWILL_RESULT': return {...state, goodwill:{...state.goodwill, open:false, status:action.status}, composer:{...state.composer, chips:action.chips||state.composer.chips}, audit:action.audit?[action.audit,...state.audit]:state.audit, toast:{kind:'success',text:action.toast}};
    case 'CLOSE_GOODWILL': return {...state, goodwill:{...state.goodwill, open:false}};
    case 'OPEN_HANDOFF': return {...state, activeScreen:'handoff_composer', handoff:{...state.handoff, open:true, status:'loading'}};
    case 'SET_HANDOFF_SUMMARY': return {...state, handoff:{...state.handoff, summary:action.summary, status:'ready'}};
    case 'SET_HANDOFF_QUEUE': return {...state, handoff:{...state.handoff, queue:action.queue}};
    case 'ESCALATE': return {...state, activeScreen:'escalation_queue', activeTicketId:null, tickets:state.tickets.map(x=>x.id===state.activeTicketId?{...x,status:'escalated'}:x), audit:[{action_id:'ACT-'+Math.floor(700+Math.random()*200),ticket_id:state.activeTicketId,type:'escalation_handoff',amount_or_sku:state.handoff.queue,actor:'Maya Torres',ai_confidence:0.85,policy_citation:'—',shopify_ref:'tier3-route',timestamp:new Date().toISOString()},...state.audit], toast:{kind:'success',text:'Escalated — SLA transferred to Tier-3 '+state.handoff.queue}, handoff:{...state.handoff,open:false}};
    case 'SET_AUDIT_FILTER': return {...state, auditFilter:action.value};
    case 'TOAST': return {...state, toast:action.toast};
    case 'CLEAR_TOAST': return {...state, toast:null};
    case 'SET_CONFIRM_PREVIEW': return {...state, confirmPreview:action.value};
    default: return state;
  }
}

