function PillButton({ children, variant='secondary', onClick, disabled, breathing, ariaLabel, leadingIcon }) {
  const base = { fontFamily:FONTS.body, fontWeight:500, fontSize:13, padding:'9px 16px', borderRadius:2, cursor:disabled?'not-allowed':'pointer', border:'1px solid '+TOK.border, display:'inline-flex', alignItems:'center', gap:8, transition:'all .18s cubic-bezier(0.4,0,0.2,1)', letterSpacing:'.2px' };
  const styles = {
    primary:{...base, background:disabled?TOK.disabledBg:TOK.accent, color:disabled?TOK.disabledTx:TOK.onAccent, border:'1px solid '+(disabled?TOK.border:TOK.accent)},
    secondary:{...base, background:TOK.surface, color:TOK.ink},
    ghost:{...base, background:'transparent', color:TOK.secondary, border:'1px solid transparent'},
